import {useEffect,useId,useRef} from 'react';
import './dialog.css';
type Item={id:string;title:string;summary:string;owner:string;updated:string};
export function ItemDialog({open,items,selectedId,onSelect,onClose,onConfirm}:{open:boolean;items:readonly Item[];selectedId:string|null;onSelect:(id:string)=>void;onClose:()=>void;onConfirm:(id:string)=>void}){
 const dialog=useRef<HTMLDialogElement>(null);const id=useId();const item=items.find(i=>i.id===selectedId);
 useEffect(()=>{const node=dialog.current;if(!node)return;if(open){const previous=document.activeElement as HTMLElement|null;if(!node.open)node.showModal();return ()=>{node.close();previous?.focus()};}node.close();},[open]);
 return <dialog ref={dialog} className="item-dialog" aria-labelledby={id+'-title'} aria-describedby={id+'-summary'} onCancel={e=>{e.preventDefault();onClose()}}>
  <header><h1 id={id+'-title'}>Choose a project</h1><p id={id+'-summary'}>Select a project to review its details before opening it.</p></header>
  <div className="master-detail"><fieldset><legend>Projects</legend>{items.length===0?<p>No projects available.</p>:items.map(i=><label key={i.id}><input type="radio" name={id+'-selection'} checked={selectedId===i.id} onChange={()=>onSelect(i.id)}/>{i.title}</label>)}</fieldset><section aria-label="Project details">{item?<><h2>{item.title}</h2><p>{item.summary}</p><dl><dt>Owner</dt><dd>{item.owner}</dd><dt>Last updated</dt><dd>{item.updated}</dd></dl></>:<p>Select a project to view details.</p>}</section></div>
  <footer><button autoFocus onClick={onClose}>Cancel</button><button disabled={!item} onClick={()=>item&&onConfirm(item.id)}>Open project</button></footer>
 </dialog>;
}
